const respuesta = pm.response.json();

if (pm.response.code === 200 && respuesta.data && respuesta.data.token) {
    pm.environment.set("token", respuesta.data.token);
}
pm.test("Login responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Devuelve un token Bearer", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.data).to.have.property("token");
    pm.expect(cuerpo.data.token_type).to.eql("Bearer");
});

pm.test("No expone la contraseña del usuario", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.data.usuario).to.not.have.property("password");
});

pm.test("Credenciales inválidas responde 401", function () {
    pm.response.to.have.status(401);
});

pm.test("Mensaje genérico, sin revelar si el correo existe", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.message).to.eql("Credenciales inválidas.");
});

pm.test("Responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Devuelve una lista paginada de libros", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo).to.have.property("data");
    pm.expect(cuerpo.data).to.be.an("array");
    pm.expect(cuerpo).to.have.property("meta");
});

pm.test("Sin token responde 401", function () {
    pm.response.to.have.status(401);
});

pm.test("El mensaje pide un token válido", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.message).to.include("token");
});

pm.test("Crear libro responde 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Devuelve el libro con sus autores", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.data).to.have.property("id");
    pm.expect(cuerpo.data.autores).to.be.an("array").that.is.not.empty;
});

