pm.test("Sin stock responde 422", function () {
    pm.response.to.have.status(422);
});

pm.test("El error indica que no hay stock", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.errors).to.have.property("libro_id");
    pm.expect(cuerpo.errors.libro_id[0]).to.include("stock");
});

pm.test("Devolver responde 200 o 422 si ya fue devuelto", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 422]);
});

pm.test("La respuesta incluye un mensaje", function () {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo).to.have.property("message");
});
